#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static char *dupstr(const char *s) {
    size_t n = strlen(s);
    char *p = malloc(n + 1);
    if (!p) {
        perror("malloc");
        exit(1);
    }
    memcpy(p, s, n + 1);
    return p;
}

static char *add_dec(const char *a, const char *b) {
    size_t la = strlen(a), lb = strlen(b);
    size_t m = la > lb ? la : lb;
    char *rev = malloc(m + 2);
    if (!rev) {
        perror("malloc");
        exit(1);
    }

    size_t i = 0;
    int carry = 0;
    while (i < m || carry) {
        int da = (i < la) ? (a[la - 1 - i] - '0') : 0;
        int db = (i < lb) ? (b[lb - 1 - i] - '0') : 0;
        int s = da + db + carry;
        rev[i++] = (char)('0' + (s % 10));
        carry = s / 10;
    }

    char *out = malloc(i + 1);
    if (!out) {
        perror("malloc");
        exit(1);
    }
    for (size_t j = 0; j < i; ++j) {
        out[j] = rev[i - 1 - j];
    }
    out[i] = '\0';
    free(rev);
    return out;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        return 1;
    }

    long long n = atoll(argv[1]);
    char *a = dupstr("0");
    char *b = dupstr("1");

    for (long long i = 0; i < n; ++i) {
        char *c = add_dec(a, b);
        free(a);
        a = b;
        b = c;
    }

    printf("%s\n", a);
    free(a);
    free(b);
    return 0;
}
